(() => {
  const D=window.RADAR,R=D.rows,M=D.model,$=s=>document.querySelector(s);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>'$'+new Intl.NumberFormat('en-US',{notation:n>=1e9?'compact':'standard',maximumFractionDigits:n>=1e9?2:0}).format(n||0);
  const pct=n=>n==null?'—':`${n>0?'+':''}${Number(n).toFixed(1)}%`;
  const share=n=>`${(n*100).toFixed(4)}%`;
  let tab='pre',sort='rank',direction=1;
  const category=$('#category'),body=$('#rows');
  $('#asof').textContent=M.as_of;
  $('#thesis').textContent='A dated-comps power law prices pre-token protocols from snapshot TVL; held-out peers grade the shipped adjustment and its band.';
  $('#model-thesis').textContent=`Runtime OLS base; ${M.grid_choice.shape} maturity and ${M.grid_choice.gf.toFixed(2)} growth factor selected by minimizing the worst held-out multiple. The range uses this model’s LOO error.`;
  $('#fitline').textContent=`a ${M.a.toFixed(4)} · b ${M.b.toFixed(4)} · R² ${M.r2.toFixed(3)} · dated n=${M.n}`;
  $('#band-kpi').textContent=`×${M.band.toFixed(2)}`;
  $('#verdict-kpi').innerHTML=`<i class="farm-chip">${M.verdicts.FARM} FARM</i><i class="thin-chip">${M.verdicts.THIN} THIN</i><i class="skip-chip">${M.verdicts.SKIP} SKIP</i>`;
  const A=M.accounting;$('#integrity').innerHTML=`<b>SNAPSHOT ACCOUNTING</b><span>${A.total} protocols</span><span>${A.ranked} ranked</span><span>${A.traded_anchors} traded anchors</span><span>${Object.values(A.excluded).reduce((s,n)=>s+n,0)} excluded by rule</span><span>${A.bad_data} bad data · autofinance mcap −1</span>`;
  $('#grid-summary').textContent=`Base OLS is fixed to log₁₀(mcap) = a + b × log₁₀(TVL). Growth and maturity are adjustment terms, not fitted regression coefficients. Select the minimum worst of split-half, LOO and walk-forward; ties resolve by lower walk-forward, then split-half. No adjustment dominates all three.`;
  $('#sh-metric').textContent=`×${M.multiples.split_half.toFixed(2)}`;$('#loo-metric').textContent=`×${M.multiples.loo.toFixed(2)}`;$('#wf-metric').textContent=`×${M.multiples.walk_forward.toFixed(2)}`;
  $('#odds-metric').textContent=`${M.tvl_odds.small.toFixed(2)} / ${M.tvl_odds.mid.toFixed(2)} / ${M.tvl_odds.large.toFixed(2)}`;
  $('#age-evidence').textContent=`Peer LOO hit rates by age: young ${M.age_odds.young.toFixed(2)} · mid ${M.age_odds.mid.toFixed(2)} · old ${M.age_odds.old.toFixed(2)}. Ranked rows have unknown age and use TVL bucket odds.`;
  $('#account-breakdown').textContent=`Excluded breakdown: ${Object.entries(A.excluded).map(([k,v])=>`${k.replace('category:','')} ${v}`).join(' · ')}. One bad-data record: autofinance, mcap_usd −1.`;
  $('#pre-count').textContent=R.length;$('#live-count').textContent=D.live.length;
  $('#blind-detail').textContent=`All held-out multiples use the same locked power-law fit process; LOO refits on 94 peers for each prediction. The 33 traded entries without listing dates are excluded from the 95 dated-peer grading set.`;
  $('#search-results').innerHTML=M.model_search.map(x=>`<tr class="${x.variant.includes('SHIPPED')?'shipped':''}"><td>${esc(x.variant)}</td><td>${esc(x.split_half)}</td><td>${esc(x.r2)}</td><td>${esc(x.time_split)}</td><td>${esc(x.outcome)}</td></tr>`).join('');
  $('#digest').innerHTML=D.categoryDigest.map(x=>`<tr><td>${esc(x.category)}</td><td>${x.row_count}</td><td>${money(x.median_tvl_usd)}</td><td>${money(x.median_implied_value_usd)}</td><td>${esc(x.top_slug)}</td></tr>`).join('');
  $('#movers-grid').innerHTML=D.weekMovers.map(x=>`<div class="move-card"><b>${esc(x.name)}</b><small>${esc(x.category||'Uncategorized')}</small><strong class="${x.change_7d>=0?'positive':'negative'}">${pct(x.change_7d)}</strong></div>`).join('');
  $('#method-list').innerHTML=D.methodNotes.map(x=>`<li>${esc(x)}</li>`).join('');
  $('#gas-grid').innerHTML=Object.entries(M.gas_costs).sort((a,b)=>a[0].localeCompare(b[0])).map(([chain,cost])=>`<span class="gas-item">${esc(chain)}<b>$${cost.toFixed(2)}</b></span>`).join('');
  [...new Set(R.map(x=>x.category).filter(Boolean))].sort().forEach(c=>category.add(new Option(c,c)));
  function visible(){const q=$('#search').value.toLowerCase(),list=tab==='pre'?R:D.live;return list.filter(x=>(!category.value||x.category===category.value)&&`${x.name} ${x.category||''} ${(x.chains||[]).join(' ')}`.toLowerCase().includes(q)).sort((x,y)=>{const a=x[sort],b=y[sort],d=typeof a==='string'?String(a).localeCompare(String(b)):(a??0)-(b??0);return d*direction;});}
  function render(){const list=visible();$('#result-count').textContent=`${list.length} entries · ${tab==='pre'?'ranked by implied value':'market cap view'}`;body.innerHTML=list.map(x=>{
    const live=tab==='live',tag=live?'LIVE':x.watchlist?'WATCHLIST':x.tvl_usd>=50000000?'ABOVE FLOOR':'EARLY';
    const verdict=live?'<span class="skip-chip">LIVE</span>':`<span class="${x.verdict.toLowerCase()}-chip">${x.verdict}</span>`;
    return `<tr data-open="${esc(x.slug)}"><td>${x.rank??'—'}</td><td><span class="protocol-name">${esc(x.name)}</span><span class="watch-tag">${tag}</span><div class="protocol-meta">${esc(x.category||'Uncategorized')} · ${esc(x.chains?.[0]||'—')}</div></td><td class="num">${money(x.tvl_usd)}</td><td class="${x.change_7d>0?'positive':x.change_7d<0?'negative':''}">${pct(x.change_7d)}</td><td>${x.age_days??'—'}d</td><td class="num">${money(live?x.mcap_usd:x.implied_value_usd)}</td><td class="num">${live?'—':`${money(x.implied_low_usd)} / ${money(x.implied_high_usd)}`}</td><td class="odds">${live?'—':`${(x.launch_odds*100).toFixed(0)}%`}</td><td>${live?'—':money(x.total_farm_cost_usd)}</td><td class="share">${live?'—':share(x.breakeven_share)}</td><td class="call">${verdict}</td></tr>`;
  }).join('');body.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>openDetail(el.dataset.open));}
  function openDetail(slug){const x=[...R,...D.live].find(v=>v.slug===slug);if(!x)return;const live=!x.farm_steps;
    const content=live?`<div class="live-banner">Live-token reference: market capitalization is observed in the snapshot. This row is not scored by the pre-token model.</div><div class="detail-metrics"><div class="metric"><span>Market cap</span><b>${money(x.mcap_usd)}</b></div><div class="metric"><span>TVL</span><b>${money(x.tvl_usd)}</b></div><div class="metric"><span>7-day change</span><b>${pct(x.change_7d)}</b></div></div>`:`<div class="detail-metrics"><div class="metric"><span>Implied value</span><b>${money(x.implied_value_usd)}</b></div><div class="metric"><span>LOO band · ×${M.band.toFixed(2)}</span><b>${money(x.implied_low_usd)} – ${money(x.implied_high_usd)}</b></div><div class="metric"><span>Plan cost</span><b>${money(x.total_farm_cost_usd)}</b></div><div class="metric"><span>Break-even share</span><b class="share">${share(x.breakeven_share)}</b></div><div class="metric"><span>Board call</span><b class="${x.verdict.toLowerCase()}-text">${x.verdict}</b></div></div><div class="eyebrow">WHY THIS RANK · #${x.rank}</div><div class="why-box">TVL ${money(x.tvl_usd)} → power-law base ${money(x.base_value_usd)}<br>Growth ${pct(x.growth_pct)} → ×${x.growth_multiplier.toFixed(3)} · maturity ×${x.maturity_multiplier.toFixed(3)}<br>Adjusted implied ${money(x.implied_value_usd)} → LOO band ${money(x.implied_low_usd)}–${money(x.implied_high_usd)}<br>Peer launch odds for this TVL tercile: <b>${(x.launch_odds*100).toFixed(0)}%</b><br>Held-out record: split-half ×${M.multiples.split_half.toFixed(2)} · LOO ×${M.multiples.loo.toFixed(2)} · walk-forward ×${M.multiples.walk_forward.toFixed(2)}<br>Plan spend ${money(x.total_farm_cost_usd)} → low-end net ${money(x.net_low_usd)}<br>Cost ÷ low band = <b>${share(x.breakeven_share)}</b> → <b>${x.verdict}</b>. You break even if your eventual allocation reaches that share of supply; compare with the protocol's actual points design.</div><div class="eyebrow">EIGHT ACTIONS · CAPITAL IS AT RISK</div><div class="step-list">${x.farm_steps.map((s,i)=>`<div class="step-card"><i>${String(i+1).padStart(2,'0')}</i><p>${esc(s)}</p></div>`).join('')}</div><p class="detail-caption">Gas and time are planning estimates from the sealed snapshot. Validate official contracts, withdrawal terms and points rules before acting.</p>`;
    $('#dialog-host').innerHTML=`<div class="shade"><article class="dialog" role="dialog" aria-modal="true" aria-label="${esc(x.name)} details"><div class="dialog-head"><div><span class="eyebrow">${live?'LIVE TOKEN':'RANKED PROTOCOL'} · ${esc(x.category||'Uncategorized')}</span><h2>${esc(x.name)}</h2><p>${esc((x.chains||[]).join(' · '))} · ${x.age_days??'—'} days recorded age</p></div><button class="close" aria-label="Close">×</button></div>${content}</article></div>`;
    $('.close').onclick=()=>$('#dialog-host').replaceChildren();$('.shade').onclick=e=>{if(e.target===e.currentTarget)$('#dialog-host').replaceChildren();};
  }
  function deepLink(){const params=new URLSearchParams(location.search);if(params.get('filter'))category.value=params.get('filter');if(params.get('tab')==='live'){tab='live';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab==='live'));}render();if(params.get('detail'))openDetail(params.get('detail'));}
  $('#search').oninput=render;category.onchange=render;
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(v=>v.classList.toggle('selected',v===b));render();});
  document.querySelectorAll('th[data-sort]').forEach(h=>h.onclick=()=>{const key=h.dataset.sort;if(sort===key)direction*=-1;else{sort=key;direction=1;}render();});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#dialog-host').replaceChildren();});
  deepLink();
})();
